  `file_size` int unsigned DEFAULT NULL,
  `width` int unsigned DEFAULT NULL,
  `height` int unsigned DEFAULT NULL,
  `alt_text` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `is_primary` tinyint(1) NOT NULL DEFAULT '0',
  `uploaded_by` bigint unsigned DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_product_image_order` (`product_id`,`sort_order`),
  KEY `idx_product_images_product` (`product_id`),
  CONSTRAINT `rc_product_images_ibfk_1` FOREIGN KEY (`product_id`) REFERENCES `rc_products` (`id`) ON DELETE CASCADE
