--
-- Table structure for table `rc_product_variants`
--

DROP TABLE IF EXISTS `rc_product_variants`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `rc_product_variants` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `product_id` bigint unsigned NOT NULL,
  `variant_sku` varchar(96) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `size` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `color` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `stock_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'outofstock',
  `stock_quantity` int DEFAULT NULL,
  `price_override` decimal(18,4) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `sort_order` smallint unsigned NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_product_variants_product` (`product_id`,`sort_order`),
  KEY `idx_product_variants_sku` (`variant_sku`),
  CONSTRAINT `fk_product_variants_product` FOREIGN KEY (`product_id`) REFERENCES `rc_products` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

