--
-- Table structure for table `rc_products`
--

DROP TABLE IF EXISTS `rc_products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `rc_products` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `source_id` bigint unsigned DEFAULT NULL,
  `slug` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `summary` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `sku` varchar(96) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `product_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'simple',
  `reference_price` decimal(18,4) DEFAULT NULL,
  `regular_price` decimal(18,4) DEFAULT NULL,
  `sale_price` decimal(18,4) DEFAULT NULL,
  `currency` char(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'USD',
  `stock_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'outofstock',
  `stock_quantity` int DEFAULT NULL,
  `featured` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `seo_title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `seo_description` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `brand` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Raspina',
  `garment_type` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `collection_name` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `season` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `fabric_composition` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `fabric_weight` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `color` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `color_family` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `pattern` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `fit` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `silhouette` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `neckline` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `sleeve_length` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `garment_length` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `closure` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `lining` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `stretch` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `care_instructions` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `origin_country` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `size_range` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `customizable_size` tinyint(1) NOT NULL DEFAULT '0',
  `customizable_fabric` tinyint(1) NOT NULL DEFAULT '0',
  `minimum_order_quantity` int unsigned DEFAULT NULL,
  `lead_time` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `wholesale_notes` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `publish_status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'published',
  `available_from` date DEFAULT NULL,
  `availability_note` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_products_slug` (`slug`),
  UNIQUE KEY `uq_products_source_id` (`source_id`),
  KEY `idx_products_sku` (`sku`),
  KEY `idx_products_stock` (`stock_status`),
  KEY `idx_products_featured_created` (`featured`,`created_at`),
  KEY `idx_products_reference_price` (`reference_price`)
) ENGINE=InnoDB AUTO_INCREMENT=307 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

